// ... Trong ProfilePage.jsx, sửa phần render Table body:
{history.map((tx, idx) => (
  <tr key={idx} className="hover:bg-white/5 border-b border-white/5">
    <td className="p-4 text-gray-400 text-sm">{new Date(tx.timestamp).toLocaleString()}</td>
    <td className="p-4 text-white font-medium">
        {tx.type === 'BUY_EXERCISE' && '🛒 Mua bài thi'}
        {tx.type === 'CREATE_FEE' && '📝 Phí đăng bài'}
        {tx.type === 'REWARD' && '🎁 Nhận thưởng'}
    </td>
    <td className="p-4 text-gray-400 text-sm italic">{tx.description || tx.type}</td>
    <td className={`p-4 text-right font-mono font-bold ${tx.amount > 0 ? 'text-emerald-400' : 'text-red-400'}`}>
        {tx.amount > 0 ? '+' : ''}{tx.amount} ETH
    </td>
    <td className="p-4 text-right">
        <a href={`https://sepolia.etherscan.io/tx/${tx.tx_hash}`} target="_blank" className="text-blue-500 hover:underline text-xs">Explore ↗</a>
    </td>
  </tr>
))}
